<script>
  import { getEntry } from '../../../actions/sync.svelte.js'
  import ModalClose from '../Modal/ModalCloseButton.svelte'
  import PopoverClose from '../Popover/PopoverCloseButton.svelte'

  // TODO: Disclosure close button!

  const { class: klass = '', target, ...p } = $props()

  let sync = $derived(getEntry(target))
  let type = $derived(sync?.type)

  const propsToPass = $derived({
    target,
    class: `drawer-close-button ${klass}`,
  })
</script>

{#if type === 'popover'}
  <PopoverClose {...propsToPass} {...p} />
{:else}
  <ModalClose {...propsToPass} {...p} />
{/if}
